<script setup lang="ts">
const props=defineProps<{csrf:string,date:string}>()
const query=computed(()=>({date:props.date}))
const {data:d,error,refresh}=await useFetch<any>('/api/platform/intraday',{query})
const busy=ref(false),message=ref('')
async function acquire(){busy.value=true;message.value='';try{await $fetch('/api/platform/intraday',{method:'POST',headers:{'x-csrf-token':props.csrf},body:{date:props.date},timeout:60000,retry:0});await refresh()}catch(e:any){message.value=e.data?.error||'Acquisizione non riuscita'}finally{busy.value=false}}
</script>
<template><section class="space-y-4"><div class="panel"><div class="flex flex-wrap gap-3 justify-between"><div><p class="eyebrow">DENTRO LA GIORNATA · {{date}}</p><h2 class="text-xl font-semibold mt-2">Battito e Body Battery nel tempo</h2></div><UButton @click="acquire" :loading="busy">Acquisisci profilo del giorno</UButton></div><p class="muted mt-3">Lettura Garmin su richiesta, con cache e conservazione degli originali. Puoi cambiare giorno nella sezione di approfondimento.</p><p class="text-amber-300 text-sm mt-3" role="status">{{message}}</p><p v-if="error" class="muted mt-3">Nessun profilo consultabile. Prova l’acquisizione quando Garmin è disponibile.</p></div><div v-if="d" class="grid lg:grid-cols-2 gap-5"><div v-for="s in d.series" class="panel"><h3 class="font-semibold mb-4">{{s.label}} · {{s.unit}}</h3><IntradayChart :key="d.date+'-'+s.metric" :points="s.points" :label="s.label" :color="s.metric==='heart_rate_bpm'?'#fb7185':'#00dc82'" :connected="s.metric==='heart_rate_bpm'"/><p class="muted mt-3">{{s.valid_n}} campioni validi su {{s.samples_n}} registrati · {{d.timezone}}</p><p class="muted mt-2">{{s.import?'Acquisito: '+s.import.fetched_at+' UTC':'Non ancora acquisito per questo giorno'}}</p></div><p class="muted lg:col-span-2">{{d.note}} Asse orario con spaziatura temporale reale; Body Battery mostra soltanto i campioni osservati.</p></div></section></template>
